type LogoProps = {
  className?: string;
};

/**
 * The sunny*r ambigram wordmark — reads identically rotated 180°.
 * The artwork (public/images/sunnyr-logo.svg, ~1.86:1, generated by
 * docs/logo/build_logo.py) is a CSS mask, so `.logo-mark` in globals.css owns
 * its color and swaps in the heavier cut on phones. Behind it, `.logo-outline`
 * draws a hairline round the edge of its lines and a soft shadow, so it stands
 * out on any background. Size it with a height utility on `className` (e.g. `h-14 w-auto`).
 */
export function Logo({ className = "" }: LogoProps) {
  return (
    <div role="img" aria-label="sunny*r" className={`logo ${className}`}>
      <span aria-hidden="true" className="logo-outline" />
      <span aria-hidden="true" className="logo-mark" />
    </div>
  );
}
